    mianownik: string;
    /** Genitive singular (dopelniacz) */
    dopelniacz: string;
    /** Accusative singular (biernik) */
    biernik: string;
    /** Nominative plural (mnoga mianownik) */
    mnoga_mianownik: string;
    /** Genitive plural (mnoga dopelniacz) */
    mnoga_dopelniacz: string;
    /** Accusative plural (mnoga biernik) */
